    24	
    25	/****************************************************************************
    26	 * Pre-processor Definitions
    27	 ****************************************************************************/
    28	
    29	/* The Huangshan Pi board registers the LSM6DSL as /dev/lsm6dsl0. */
    30	#define IMU_DEVICE_PATH         "/dev/lsm6dsl0"
    31	
    32	/* Default thresholds (in m/s^2) */
    33	
    34	#define DEFAULT_MOVE_THRESHOLD  0.5f
    35	#define DEFAULT_RUN_THRESHOLD   2.0f
    36	#define DEFAULT_FALL_THRESHOLD  15.0f
    37	
    38	#define FALL_FREEFALL_THRESHOLD 0.5f
    39	#define FALL_IMPACT_THRESHOLD   8.0f
    40	#define FALL_REST_MIN           0.7f
    41	#define FALL_REST_MAX           1.3f
    42	#define FALL_FREEFALL_WINDOW_MS 500
    43	#define FALL_FREEFALL_MIN_MS    100
    44	#define FALL_IMPACT_WINDOW_MS   2000
    45	#define FALL_CONFIRM_HOLD_MS    2000
    46	
    47	/****************************************************************************
    48	 * Private Functions
    49	 ****************************************************************************/
    50	
    51	static float calculate_magnitude(float x, float y, float z)
    52	{
    53	  return sqrtf(x * x + y * y + z * z);
    54	}
    55	
    56	static uint32_t imu_now_ms(void)
    57	{
    58	  struct timespec ts;
    59	
    60	  if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
    61	    {
    62	      return (uint32_t)time(NULL) * 1000;
    63	    }
    64	
    65	  return (uint32_t)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
    66	}
    67	
    68	static void reset_fall_detector(imu_sensor_t *imu)
    69	{
    70	  imu->fall_detector.stage = FALL_STAGE_NONE;
    71	  imu->fall_detector.stage_start_ms = 0;
    72	  imu->fall_detector.confirmed = false;
    73	}
    74	
    75	static void update_fall_detector(imu_sensor_t *imu, float accel_mag)
    76	{
    77	  uint32_t now = imu_now_ms();
    78	  uint32_t elapsed = now - imu->fall_detector.stage_start_ms;
    79	
    80	  switch (imu->fall_detector.stage)
    81	    {
    82	      case FALL_STAGE_NONE:
    83	        if (accel_mag < FALL_FREEFALL_THRESHOLD)
    84	          {
    85	            imu->fall_detector.stage = FALL_STAGE_FREEFALL;
    86	            imu->fall_detector.stage_start_ms = now;
    87	            imu->fall_detector.confirmed = false;
    88	          }
    89	        break;
    90	
    91	      case FALL_STAGE_FREEFALL:
    92	        if (accel_mag > FALL_IMPACT_THRESHOLD &&
    93	            elapsed >= FALL_FREEFALL_MIN_MS &&
    94	            elapsed <= FALL_FREEFALL_WINDOW_MS)
    95	          {
    96	            imu->fall_detector.stage = FALL_STAGE_IMPACT;
    97	            imu->fall_detector.stage_start_ms = now;
    98	          }
    99	        else if (accel_mag >= FALL_FREEFALL_THRESHOLD ||
   100	                 elapsed > FALL_FREEFALL_WINDOW_MS)
   101	          {
   102	            /* Freefall must remain below 0.5g until the impact sample. */
   103	            reset_fall_detector(imu);
   104	          }
   105	        break;
   106	
   107	      case FALL_STAGE_IMPACT:
   108	        if (accel_mag >= FALL_REST_MIN && accel_mag <= FALL_REST_MAX &&
   109	            elapsed <= FALL_IMPACT_WINDOW_MS)
   110	          {
   111	            imu->fall_detector.stage = FALL_STAGE_STILL;
   112	            imu->fall_detector.stage_start_ms = now;
   113	            imu->fall_detector.confirmed = true;
   114	            syslog(LOG_WARNING,
   115	                   "[IMU] Fall confirmed after freefall and impact\n");
   116	          }
   117	        else if (elapsed > FALL_IMPACT_WINDOW_MS)
   118	          {
   119	            reset_fall_detector(imu);
   120	          }
   121	        break;
   122	
   123	      case FALL_STAGE_STILL:
   124	        if (elapsed > FALL_CONFIRM_HOLD_MS)
   125	          {
   126	            reset_fall_detector(imu);
   127	          }
   128	        break;
   129	
   130	      default:
   131	        reset_fall_detector(imu);
   132	        break;
   133	    }
   134	
   135	  imu->motion.fall_detected = imu->fall_detector.confirmed;
   136	}
   137	
   138	static void update_motion_state(imu_sensor_t *imu, imu_data_t *data)
   139	{
   140	  float accel_mag = calculate_magnitude(data->accel_x,
   141	                                        data->accel_y,
   142	                                        data->accel_z);
   143	  float gyro_mag = calculate_magnitude(data->gyro_x,
   144	                                       data->gyro_y,
   145	                                       data->gyro_z);
   146	
   147	  /* Confirm a fall only after freefall, impact, and post-impact stillness. */
   148	
   149	  update_fall_detector(imu, accel_mag);
   150	
   151	  /* Check for running (high acceleration + gyro) */
   152	
   153	  if (accel_mag > imu->threshold_run && gyro_mag > 1.0f)
   154	    {
   155	      imu->motion.is_running = true;
   156	      imu->motion.is_moving = true;
   157	      imu->motion.last_motion_time = time(NULL);
   158	      imu->motion.motion_count++;
   159	    }
   160	  /* Check for moving (moderate acceleration) */
   161	
   162	  else if (accel_mag > imu->threshold_move)
   163	    {
   164	      imu->motion.is_moving = true;
   165	      imu->motion.is_running = false;
   166	      imu->motion.last_motion_time = time(NULL);
   167	      imu->motion.motion_count++;
   168	    }
   169	  else
   170	    {
   171	      /* No significant motion */
   172	
   173	      if (time(NULL) - imu->motion.last_motion_time > 5)
   174	        {
   175	          imu->motion.is_moving = false;
   176	          imu->motion.is_running = false;
   177	        }
   178	    }
   179	
   180	  imu->motion.motion_intensity = accel_mag;
   181	}
