   187	int imu_sensor_init(imu_sensor_t *imu)
   188	{
   189	  memset(imu, 0, sizeof(imu_sensor_t));
   190	
   191	  /* Open IMU device */
   192	
   193	  imu->fd = open(IMU_DEVICE_PATH, O_RDONLY);
   194	  if (imu->fd < 0)
   195	    {
   196	      syslog(LOG_ERR, "[IMU] Failed to open %s: %d\n",
   197	             IMU_DEVICE_PATH, errno);
   198	      return VELAWEAR_ERR_IO;
   199	    }
   200	
   201	  /* Start the sensor before requesting samples.  The LSM6DSL driver exposes
   202	   * data through SNIOC_LSM6DSLSENSORREAD rather than read(). */
   203	  if (ioctl(imu->fd, SNIOC_START, 0) < 0)
   204	    {
   205	      syslog(LOG_ERR, "[IMU] Failed to start %s: %d\n",
   206	             IMU_DEVICE_PATH, errno);
   207	      close(imu->fd);
   208	      imu->fd = -1;
   209	      return VELAWEAR_ERR_IO;
   210	    }
   211	
   212	  /* Set default thresholds */
   213	
   214	  imu->threshold_move = DEFAULT_MOVE_THRESHOLD;
   215	  imu->threshold_run = DEFAULT_RUN_THRESHOLD;
   216	  imu->threshold_fall = DEFAULT_FALL_THRESHOLD;
   217	
   218	  imu->initialized = true;
   219	  imu->buffer_index = 0;
   220	
   221	  syslog(LOG_INFO, "[IMU] Initialized\n");
