   236	int imu_sensor_read(imu_sensor_t *imu, imu_data_t *data)
   237	{
   238	  struct lsm6dsl_sensor_data_s raw;
   239	  int ret;
   240	
   241	  if (!imu->initialized)
   242	    {
   243	      return VELAWEAR_ERR_IO;
   244	    }
   245	
   246	  ret = ioctl(imu->fd, SNIOC_LSM6DSLSENSORREAD,
   247	              (unsigned long)&raw);
   248	  if (ret < 0)
   249	    {
   250	      syslog(LOG_ERR, "[IMU] Read failed: %d\n", errno);
   251	      return VELAWEAR_ERR_IO;
   252	    }
   253	
   254	  /* Convert raw data to float */
   255	
   256	  data->accel_x = raw.x_data / 1000.0f;
   257	  data->accel_y = raw.y_data / 1000.0f;
   258	  data->accel_z = raw.z_data / 1000.0f;
   259	  data->gyro_x = raw.g_x_data / 1000.0f;
   260	  data->gyro_y = raw.g_y_data / 1000.0f;
   261	  data->gyro_z = raw.g_z_data / 1000.0f;
   262	  data->timestamp = time(NULL);
   263	
   264	  /* Store in buffer */
   265	
   266	  imu->buffer[imu->buffer_index] = *data;
   267	  imu->buffer_index = (imu->buffer_index + 1) % IMU_BUFFER_SIZE;
   268	
   269	  /* Update motion state */
   270	
   271	  update_motion_state(imu, data);
   272	
   273	  return VELAWEAR_OK;
   274	}
